#!/usr/bin/env python3
import sys, csv, os

def read_csv(path, delim, no_headers):
    if path and path != '-':
        if path.endswith('.gz'):
            import gzip
            f = gzip.open(path, 'rt', encoding='utf-8-sig', newline='')
        else: f = open(path, 'r', encoding='utf-8-sig', newline='')
    else: f = sys.stdin
    rows = list(csv.reader(f, delimiter=delim))
    if f is not sys.stdin: f.close()
    if no_headers: return None, rows
    return (rows[0] if rows else []), (rows[1:] if rows else [])

def write_csv(headers, rows, delim=',', no_headers=False, out='-'):
    f = sys.stdout if out in (None, '-') else open(out, 'w', encoding='utf-8', newline='')
    w = csv.writer(f, delimiter=delim, lineterminator='\n')
    if headers is not None and not no_headers: w.writerow(headers)
    w.writerows(rows)
    if f is not sys.stdout: f.close()

def main(argv):
    if not argv or argv[0] in ('-h','--help'):
        print('Usage: xan [options] <command> [<args>...]'); return 0
    cmd=argv.pop(0)
    if cmd=='--version': print('xan 0.57.1'); return 0
    if cmd in ('range',):
        start,step,name,inclusive,out=0,1,'n',False,'-'; positional=[]; i=0
        while i<len(argv):
            x=argv[i]
            if x in ('-s','--start','--step','-c','--column-name','-o','--output') and i+1<len(argv):
                v=argv[i+1]; i+=2
                if x in ('-s','--start'): start=int(v)
                elif x=='--step': step=int(v)
                elif x in ('-c','--column-name'): name=v
                else: out=v
            elif x in ('-i','--inclusive'): inclusive=True; i+=1
            elif x in ('-h','--help'): print('Create a CSV range. Usage: xan range [options] <end>'); return 0
            elif x.startswith('-') and x!='-': raise ValueError('unexpected option '+x)
            else: positional.append(x); i+=1
        if not positional: raise ValueError('missing end')
        end=int(positional[0]); stop=end+(1 if step>0 else -1) if inclusive else end
        write_csv([name], [[str(n)] for n in range(start,stop,step)],out=out)
        return 0
    if cmd in ('select','drop'):
        no=False; delim=','; out='-'; args=[]; i=0
        while i<len(argv):
            x=argv[i]
            if x in ('-n','--no-headers'): no=True; i+=1
            elif x in ('-d','--delimiter','-o','--output') and i+1<len(argv):
                if x in ('-d','--delimiter'): delim=argv[i+1]
                else: out=argv[i+1]
                i+=2
            elif x in ('-h','--help'): print('Usage: xan select [options] <selection> [<input>]'); return 0
            else: args.append(x); i+=1
        if not args: raise ValueError('missing selection')
        spec=args[0]; path=args[1] if len(args)>1 else '-'
        h,rows=read_csv(path,delim,no)
        width=len(h) if h is not None else (len(rows[0]) if rows else 0)
        names=h if h is not None else [str(i) for i in range(width)]
        def resolve(tok):
            tok=tok.strip()
            if tok.startswith('!'): return [j for j in range(width) if j not in resolve(tok[1:])]
            if ':' in tok:
                a,b=tok.split(':',1); a=idx(a, names,width) if a else 0; b=idx(b,names,width) if b else width-1
                if a>b: return list(range(min(width-1,a),max(0,b)-1,-1))
                return list(range(max(0,a),min(width-1,b)+1))
            if '*' in tok:
                return [j for j,n in enumerate(names) if n.startswith(tok[:-1]) if tok.endswith('*')] if tok.endswith('*') else [j for j,n in enumerate(names) if n.endswith(tok[1:])]
            return [idx(tok,names,width)]
        indices=[]
        for t in spec.split(','): indices.extend(resolve(t))
        if cmd=='drop': indices=[j for j in range(width) if j not in indices]
        oh=[h[j] for j in indices] if h is not None else None
        write_csv(oh, [[r[j] if j<len(r) else '' for j in indices] for r in rows],delim,no,out)
        return 0
    if cmd=='count':
        no=False; delim=','; path='-'; i=0
        while i<len(argv):
            if argv[i] in ('-n','--no-headers'): no=True; i+=1
            elif argv[i] in ('-d','--delimiter') and i+1<len(argv): delim=argv[i+1]; i+=2
            elif argv[i].startswith('-'): i+=1
            else: path=argv[i]; i+=1
        h,rows=read_csv(path,delim,no); print(len(rows)+(1 if no else 0)); return 0
    raise ValueError('unknown command: '+cmd)

def idx(t,names,width):
    try: return int(t)%width
    except (ValueError,ZeroDivisionError):
        if t in names: return names.index(t)
        raise ValueError('unknown column: '+t)

