            if argv[i] in ('-n','--no-headers'): no=True; i+=1
            elif argv[i] in ('-d','--delimiter') and i+1<len(argv): delim=argv[i+1]; i+=2
            elif argv[i] in ('-o','--output') and i+1<len(argv): out=argv[i+1]; i+=2
            elif argv[i] in ('-t','--threads') and i+1<len(argv): i+=2
            elif argv[i] in ('-p','--parallel','-a','--approx'): i+=1
            elif argv[i].startswith('-'): i+=1
            else: path=argv[i]; i+=1
        if delim is None: _, delim = read_delim(path)
        h,rows=read_csv(path,delim,no)
        f=sys.stdout if out=='-' else open(out,'w',encoding='utf-8')
        print(len(rows),file=f)
        if f is not sys.stdout: f.close()
        return 0
    if cmd in ('headers','h','head','tail','behead','guillotine','reverse'):
        no=False; delim=None; out='-'; just=False; csv_headers=False; limit=10; append=False; start_index=0; path='-'; args=[]; i=0
        while i<len(argv):
            x=argv[i]
            if x in ('-n','--no-headers'): no=True; i+=1
            elif x in ('-j','--just-names'): just=True; i+=1
            elif x=='--csv' and cmd in ('headers','h'): csv_headers=True; i+=1
            elif x in ('-A','--append') and cmd in ('behead','guillotine'): append=True; i+=1
            elif x in ('-d','--delimiter','-o','--output','-l','--limit','-s','--start') and i+1<len(argv):
                v=argv[i+1]; i+=2
                if x in ('-d','--delimiter'): delim=v
                elif x in ('-o','--output'): out=v
                elif x in ('-l','--limit'): limit=parse_u64(v,'--limit')
                elif cmd in ('headers','h'): start_index=parse_u64(v,'--start')
                else: raise ValueError('unknown option: '+x)
            elif x in ('-h','--help'):
                print('Usage: xan '+cmd+' [options] [<input>]'); return 0
            else: args.append(x); i+=1
        if cmd in ('headers','h'):
            paths=args or [path]
            file_headers=[]
            for header_path in paths:
                use_delim=delim
                if use_delim is None: _, use_delim = read_delim(header_path)
                h,rows=read_csv(header_path,use_delim,False)
                file_headers.append(h or [])
            f=sys.stdout if out=='-' else open(out,'w',encoding='utf-8',newline='')
            if csv_headers:
                writer=csv.writer(f,delimiter=',',lineterminator='\n')
                writer.writerow(['<stdin>' if p=='-' else p for p in paths])
                width=max((len(h) for h in file_headers),default=0)
                writer.writerows([[h[i] if i<len(h) else '' for h in file_headers] for i in range(width)])
            else:
                multiple=len(paths)>1
                for k,(header_path,hh) in enumerate(zip(paths,file_headers)):
                    if multiple:
                        if k: print(file=f)
                        print(header_path,file=f)
                    for j,name in enumerate(hh): print(name if just else f'{j+start_index}   {name}',file=f)
                if multiple:
                    if any(hh!=file_headers[0] for hh in file_headers[1:]):
                        first=set(file_headers[0]); divergent=[]
                        for hh in file_headers[1:]:
                            divergent.extend(x for x in file_headers[0] if x not in hh and x not in divergent)
                            divergent.extend(x for x in hh if x not in first and x not in divergent)
                        print("\nAll files don't have the same headers!",file=f)
                        if divergent: print('Diverging headers: '+', '.join(divergent),file=f)
            if f is not sys.stdout: f.close()
            return 0
        path=args[0] if args else path
        if delim is None: _, delim = read_delim(path)
        h,rows=read_csv(path,delim,no)
        if cmd in ('behead','guillotine'):
            if append:
                if out == '-': raise ValueError('--append requires --output')
                import os
                existing = os.path.exists(out) and os.path.getsize(out) > 0
                if not existing and h is not None: rows=[h]+rows
                f=open(out,'a',encoding='utf-8',newline='')
                csv.writer(f,delimiter=',',lineterminator='\n').writerows(rows)
                f.close()
            else:
                if h is not None: rows=[h]+rows
                write_csv(None,rows,',',True,out)
            return 0
        if cmd=='reverse':
            write_csv(h,rows[::-1],',',no,out); return 0
        chosen=rows[:limit] if cmd=='head' and limit>0 else rows if cmd=='head' else rows[-limit:] if limit else []
        write_csv(h,chosen,',',no,out); return 0
    if cmd in ('unpivot','pivot-longer','explode','implode','pivot','pivot-wider'):
        import reshape
        if reshape.run(cmd, argv): return 0
    if cmd == 'fmt':
        import fmtcmd
        return fmtcmd.run(argv)
    raise ValueError('unknown command: '+cmd)

def idx(t,names,width):
    try: n=int(t)
    except ValueError:
        if t in names: return names.index(t)
        raise ValueError('unknown column: '+t)
    else:
        if n < 0: n += width
        if n < 0 or n >= width: raise ValueError(f'column index {t} is out of bounds')
        return n

def read_delim(path):
    parts=(path or '').lower().split('.')
    ext=parts[-2] if len(parts)>1 and parts[-1]=='gz' else (parts[-1] if len(parts)>1 else '')
    return None, {'tsv':'\t','tab':'\t','psv':'|','ssv':';','scsv':';','cdx':' '}.get(ext, ',')

if __name__=='__main__':
    try: sys.exit(main(sys.argv[1:]))
    except Exception as e: print('error: '+str(e),file=sys.stderr); sys.exit(1)
